// Enquiry log visual baselines (#875, #87 part 3): every viewport × theme project (360/768/1280,
// light and dark): the list, the new enquiry dialog, the conflict panel, the close dialog, and the
// empty, error, offline and denied states. The seeded enquiries are fixed, so nothing needs a
// frozen clock. Baselines live in e2e/__screenshots__ and are only ever generated by the e2e
// workflow's `update_snapshots` dispatch in the pinned Playwright image (see e2e/README.md);
// without one the test is skipped.
import { existsSync } from 'node:fs';

import type { Locator, Page, TestInfo } from '@playwright/test';

import type { AsUser } from '../../fixtures/auth.ts';
import { MATTERS_WORKSPACE } from '../../fixtures/matters-data.ts';
import { expect, test } from '../../fixtures/index.ts';

import {
  ENQUIRIES,
  emptyEnquiries,
  enableEnquiryLog,
  enquiriesPath,
  enquiryRow,
  openEnquiries,
  seedEnquiries,
  volatile,
} from './enquiries.helpers.ts';

function skipWithoutBaseline(testInfo: TestInfo, name: string) {
  const baseline = testInfo.snapshotPath(name, { kind: 'screenshot' });
  test.skip(
    testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
    'no baseline yet: dispatch the e2e workflow with update_snapshots',
  );
}

interface Shot {
  name: string;
  /** `database` is the worker database. Returns the element to shoot, or the page. */
  setUp: (page: Page, asUser: AsUser, database: string) => Promise<Locator | null>;
}

const rows = (page: Page) => page.locator('[data-enquiry-row]');

const SHOTS: readonly Shot[] = [
  {
    name: 'enquiries-list.png',
    setUp: async (page, asUser, database) => {
      await seedEnquiries(database);
      await openEnquiries(page, asUser);
      await expect(rows(page).first()).toBeVisible();
      return null;
    },
  },
  {
    name: 'enquiries-new.png',
    setUp: async (page, asUser, database) => {
      await seedEnquiries(database);
      await openEnquiries(page, asUser);
      await page.locator('[data-slot="new-enquiry"]').first().click();
      const dialog = page.getByRole('dialog');
      await expect(dialog).toBeVisible();
      return dialog;
    },
  },
  {
    name: 'enquiries-conflict-panel.png',
    setUp: async (page, asUser, database) => {
      await seedEnquiries(database);
      await openEnquiries(page, asUser);
      const row = enquiryRow(page, ENQUIRIES.logged);
      await row.getByRole('button', { name: 'Review' }).click();
      await expect(row.locator('[data-slot="conflict-panel"]')).toBeVisible();
      return row;
    },
  },
  {
    name: 'enquiries-close.png',
    setUp: async (page, asUser, database) => {
      await seedEnquiries(database);
      await openEnquiries(page, asUser);
      await enquiryRow(page, ENQUIRIES.logged).getByRole('button', { name: 'Close' }).click();
      const dialog = page.getByRole('dialog');
      await expect(dialog).toBeVisible();
      return dialog;
    },
  },
  {
    name: 'enquiries-empty.png',
    setUp: async (page, asUser, database) => {
      await emptyEnquiries(database);
      await openEnquiries(page, asUser);
      await expect(page.locator('main [data-pattern-state="empty"]')).toBeVisible();
      return null;
    },
  },
  {
    name: 'enquiries-error.png',
    setUp: async (page, asUser, database) => {
      await seedEnquiries(database);
      await openEnquiries(page, asUser);
      await page.goto(`/w/${MATTERS_WORKSPACE}/${enquiriesPath('__state=error')}`);
      await expect(page.locator('main [data-pattern-state="error"]')).toBeVisible({
        timeout: 15_000,
      });
      return null;
    },
  },
  {
    name: 'enquiries-offline.png',
    setUp: async (page, asUser, database) => {
      await seedEnquiries(database);
      await openEnquiries(page, asUser, { path: enquiriesPath('__state=offline') });
      await expect(page.locator('[data-enquiries-offline]')).toBeVisible();
      return null;
    },
  },
  {
    name: 'enquiries-denied.png',
    setUp: async (page, asUser, database) => {
      await seedEnquiries(database);
      await openEnquiries(page, asUser, { role: 'clerk' });
      return null;
    },
  },
];

test.describe('enquiry log visual baselines', () => {
  for (const shot of SHOTS) {
    test(
      shot.name.replace(/\.png$/, ''),
      { tag: '@visual' },
      async ({ page, asUser, db }, testInfo) => {
        skipWithoutBaseline(testInfo, shot.name);
        await enableEnquiryLog(db.name);
        const target = await shot.setUp(page, asUser, db.name);
        const options = { animations: 'disabled', caret: 'hide', mask: volatile(page) } as const;
        if (target === null) await expect(page).toHaveScreenshot(shot.name, options);
        else await expect(target).toHaveScreenshot(shot.name, options);
      },
    );
  }
});
